using namespace std;

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, M, K;
    cin >> N >> M >> K;
    string s;
    cin >> s;
    vector<string> w(M);
    for(auto &x : w) cin >> x;
    long long P;
    cin >> P;

    // posições das letras borradas, em ordem
    vector<int> pos;
    for(int i = 0; i < N; i++)
        if(s[i] == '#') pos.push_back(i);

    // ordena as letras de cada palavra (a ordem lexicográfica das senhas
    // corresponde à ordem das letras escolhidas em cada posição borrada)
    for(int i = 0; i < M; i++)
        sort(w[i].begin(), w[i].end());

    // teto para evitar overflow (P <= 1e9, então qualquer contagem acima disso
    // pode ser tratada como "grande o suficiente")
    const unsigned long long CAP = 2000000000ULL;
    auto mulcap = [&](unsigned long long a, unsigned long long b) -> unsigned long long {
        if(a == 0 || b == 0) return 0;
        if(a > CAP / b) return CAP;
        unsigned long long r = a * b;
        return r > CAP ? CAP : r;
    };

    // suf[i] = produto de K das posições borradas i..M-1 (com teto)
    vector<unsigned long long> suf(M + 1, 1);
    for(int i = M - 1; i >= 0; i--)
        suf[i] = mulcap(suf[i + 1], (unsigned long long)K);

    // construção gulosa: para cada posição borrada, cada letra da palavra
    // (em ordem) corresponde a um bloco de suf[i+1] senhas consecutivas
    unsigned long long rem = (unsigned long long)P;
    for(int i = 0; i < M; i++){
        unsigned long long block = suf[i + 1];
        bool chosen = false;
        for(char c : w[i]){
            if(rem > block){
                rem -= block;
            } else {
                s[pos[i]] = c;
                chosen = true;
                break;
            }
        }
        if(!chosen) s[pos[i]] = w[i].back(); // fallback defensivo (não deveria ocorrer)
    }

    cout << s << "\n";
    return 0;
}
